-- ============================================================
-- IMPORT ESTOQUE TRYO (1.384 produtos Omie) — Code Web aplica
-- Backup + contagem pre/pos + upsert por (company_id, codigo)
-- tipo_item_sped=00 (Mercadoria Revenda) default; contador refina
-- ============================================================

-- PRE-REQUISITO: indice unico p/ o upsert (idempotente)
CREATE UNIQUE INDEX IF NOT EXISTS ux_erp_produtos_company_codigo
  ON public.erp_produtos (company_id, codigo);

-- BACKUP (RD-54)
CREATE SCHEMA IF NOT EXISTS bkp;
DROP TABLE IF EXISTS bkp.produtos_tryo_import_20260813;
CREATE TABLE bkp.produtos_tryo_import_20260813 AS
  SELECT * FROM public.erp_produtos WHERE company_id='918c3ea4-770d-4a10-9200-f9c21f92a1f6';

-- CONTAGEM PRE
SELECT 'PRE' etapa, count(*) total,
       count(*) FILTER (WHERE COALESCE(preco_custo_medio,0)>0) com_custo
  FROM public.erp_produtos WHERE company_id='918c3ea4-770d-4a10-9200-f9c21f92a1f6';

-- UPSERT
ON CONFLICT (company_id, codigo) DO UPDATE SET
  preco_custo        = EXCLUDED.preco_custo,
  preco_custo_medio  = EXCLUDED.preco_custo_medio,
  tipo_item_sped     = COALESCE(public.erp_produtos.tipo_item_sped, EXCLUDED.tipo_item_sped),
  unidade_inventario = COALESCE(public.erp_produtos.unidade_inventario, EXCLUDED.unidade_inventario),
  custo_medio_origem = 'OMIE_CMC',
  updated_at         = now();
-- NOTA: em conflito NAO sobrescreve nome/unidade existentes (preserva dado real)

-- CONTAGEM POS
SELECT 'POS' etapa, count(*) total,
       count(*) FILTER (WHERE COALESCE(preco_custo_medio,0)>0) com_custo,
       count(*) FILTER (WHERE tipo_item_sped='00') tipo00
  FROM public.erp_produtos WHERE company_id='918c3ea4-770d-4a10-9200-f9c21f92a1f6';

